+                       pose.linear_velocity().y() * pose.linear_velocity().y());
+    trajectory_point->set_v(v);
+    auto a = std::sqrt(
+        pose.linear_acceleration().x() * pose.linear_acceleration().x() +
+        pose.linear_acceleration().y() * pose.linear_acceleration().y());
+    trajectory_point->set_a(a);
+  }
 }
 
