+    for (int j = 0; j < road.passage_size(); ++j) {
+      const auto& passage = routing_response.road(i).passage(j);
+      for (int k = 0; k < passage.segment_size(); ++k) {
+        const auto& segment = passage.segment(k);
+        length += (segment.end_s() - segment.start_s());
+      }
+    }
+  }
+  return length;
+}
