-	/** @brief Constructor with row major formatting */
-	Matrix3x3(const tf2Scalar& xx, const tf2Scalar& xy, const tf2Scalar& xz,
-		const tf2Scalar& yx, const tf2Scalar& yy, const tf2Scalar& yz,
