-	TF2SIMD_FORCE_INLINE	Quaternion& operator+=(const Quaternion& q)
-	{
-		m_floats[0] += q.x(); m_floats[1] += q.y(); m_floats[2] += q.z(); m_floats[3] += q.m_floats[3];
