-	tf2Scalar dot(const Quaternion& q) const
-	{
-		return m_floats[0] * q.x() + m_floats[1] * q.y() + m_floats[2] * q.z() + m_floats[3] * q.m_floats[3];
-	}
-
-  /**@brief Return the length squared of the quaternion */
-	tf2Scalar length2() const
