-	tf2Scalar  d = v0.dot(v1);
-
-	if (d < -1.0 + TF2SIMD_EPSILON)
-	{
-		Vector3 n,unused;
-		tf2PlaneSpace1(v0,n,unused);
-		return Quaternion(n.x(),n.y(),n.z(),0.0f); // just pick any vector that is orthogonal to v0
