-	tf2Scalar  s = tf2Sqrt((1.0f + d) * 2.0f);
-	tf2Scalar rs = 1.0f / s;
-
-	return Quaternion(c.getX()*rs,c.getY()*rs,c.getZ()*rs,s * 0.5f);
