-struct tf2TypedObject
-{
-	tf2TypedObject(int objectType)
-		:m_objectType(objectType)
-	{
-	}
-	int	m_objectType;
-	inline int getObjectType() const
-	{
-		return m_objectType;
-	}
-};
-#endif //TF2SIMD___SCALAR_H

