-TF2SIMD_FORCE_INLINE Vector3 Vector3::rotate( const Vector3& wAxis, const tf2Scalar angle ) const
-{
-	// wAxis must be a unit lenght vector
-
-	Vector3 o = wAxis * wAxis.dot( *this );
-	Vector3 x = *this - o;
-	Vector3 y;
-
-	y = wAxis.cross( *this );
-
-	return ( o + x * tf2Cos( angle ) + y * tf2Sin( angle ) );
-}
