-        result_quat = inv_target_quat * source_to_top_quat;
-      } break;
-    };
-
-    time = _time;
-  }
-
-  TransformStorage st;
-  Time time;
-  tf2::Quaternion source_to_top_quat;
-  tf2::Vector3 source_to_top_vec;
-  tf2::Quaternion target_to_top_quat;
-  tf2::Vector3 target_to_top_vec;
