-struct TimeAndFrameIDFrameComparator {
-  TimeAndFrameIDFrameComparator(CompactFrameID id) : id(id) {}
-
-  bool operator()(const P_TimeAndFrameID& rhs) const {
-    return rhs.second == id;
-  }
-
-  CompactFrameID id;
