-    mstream << "  broadcaster: '" << authority << "'" << std::endl;
-    mstream << "  rate: " << rate << std::endl;
-    mstream << "  most_recent_transform: "
-            << time_to_sec(cache->getLatestTimestamp()) << std::endl;
-    mstream << "  oldest_transform: " << time_to_sec(cache->getOldestTimestamp())
-            << std::endl;
-    if (current_time > 0) {
