-
-  lru_cache.Put(id0, ch0);
-  int size = lru_cache.Size();
-  ASSERT_EQ(size, 3);
-
-  str = lru_cache.ClearOne();
-  ASSERT_TRUE(strcmp(str->c_str(), "bbb"));
-}
