-  ActiveSetSpline1dSolver pg(x_knots, 6);
-
-  auto* spline_constraint = pg.mutable_spline_constraint();
-  auto* spline_kernel = pg.mutable_spline_kernel();
-  ASSERT_TRUE(spline_constraint != nullptr);
