-    default:
-      ins_.set_type(apollo::drivers::gnss::Ins::INVALID);
-  }
-
-  double seconds =
-      pva->gps_week * newtonm2::SECONDS_PER_WEEK + pva->gps_seconds;
-  if (ins_.measurement_time() != seconds) {
-    ins_.set_measurement_time(seconds);
