-// An parser for decoding binary messages from a Starneto Newton-M2 receiver.
-// The following messages must be logged in order for this parser to work
-// properly.
-//
-
-#pragma once
-
-#include <cmath>
-#include <iostream>
-#include <limits>
-#include <memory>
-#include <vector>
